import{_ as l,a0 as n,w as m,s as r,I as o,x as e,a1 as i,A as s,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"如何在 VirtualBox 中安裝 SteamOS | LCTT x X-CMD","titleTemplate":false,"description":"如何在 VirtualBox 中安裝 SteamOS | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 VirtualBox 中安裝 SteamOS | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 VirtualBox 中安裝 SteamOS | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/How to Install SteamOS in VirtualBox","title":"如何在 VirtualBox 中安裝 SteamOS","tag":"201312","desc":""},"relativePath":"201312/How to Install SteamOS in VirtualBox.md","filePath":"[post].md"}'),S={name:"201312/How to Install SteamOS in VirtualBox.md"};function u(d,t,x,O,g,f){const a=n("Link");return m(),r("div",null,[t[16]||(t[16]=o("h1",{id:"如何在-virtualbox-中安裝-steamos",tabindex:"-1"},[e("如何在 VirtualBox 中安裝 SteamOS "),o("a",{class:"header-anchor",href:"#如何在-virtualbox-中安裝-steamos","aria-label":"Permalink to “如何在 VirtualBox 中安裝 SteamOS”"},"​")],-1)),t[17]||(t[17]=o("p",null,[o("strong",null,"下面的教程將指導 Linuxer 在 VirtualBox 中全新安裝 SteamOS GNU/Linux。")],-1)),t[18]||(t[18]=o("p",null,"如你已經瞭解的那樣，SteamOS Linux 已經在12月13日正式發佈了。作為一款基於 Debian GNU/Linux 的操作系統，它默認使用了 GNOME 作為桌面環境，當然這是可選的。",-1)),t[19]||(t[19]=o("p",null,"如果硬件上沒有問題的話，比如你的電腦擁有強大遊戲顯卡，且支持UEFI的，那麼安裝 SteamOS 將是一件非常容易的事情，然而，因為 Valve 並沒有發佈 SteamOS 的 ISO 鏡像，在安裝過程中可能並不是那麼順利。",-1)),t[20]||(t[20]=o("p",null,"下面的教程由兩個重要的部分組成，第一部分將會幫助你用 Valve 官方的 SteamOSInstaller.zip 來創建一個 ISO 鏡像；如果你不希望在自己的電腦上真正安裝，那麼第二部分將會告訴你如何在 VirtualBox 中來體驗 SteamOS。",-1)),o("p",null,[t[1]||(t[1]=e("在一開始你需要一個已經正確安裝的最新的 VirtualBox。當然，你還需要一款叫做",-1)),i(a,{href:"http://linux.softpedia.com/get/Programming/Libraries/GNU-xorriso-36759.shtml"},{default:s(()=>[...t[0]||(t[0]=[e("GNUxorriso",-1)])]),_:1}),t[2]||(t[2]=e("的軟件用來製作 ISO 鏡像。",-1))]),t[21]||(t[21]=o("h3",{id:"第一步-製作-steamiso-鏡像",tabindex:"-1"},[e("第一步，製作 SteamISO 鏡像 "),o("a",{class:"header-anchor",href:"#第一步-製作-steamiso-鏡像","aria-label":"Permalink to “第一步，製作 SteamISO 鏡像”"},"​")],-1)),o("p",null,[i(a,{href:"http://linux.softpedia.com/get/System/Operating-Systems/Linux-Distributions/SteamOS-103040.shtml"},{default:s(()=>[...t[3]||(t[3]=[e("從 Softpedia 下載 SteamOSInstaller.zip",-1)])]),_:1}),t[4]||(t[4]=e("，將它保存到你的 home 目錄下並解壓縮。完畢之後你將會看到 SteamOSInstaller 文件夾。現在，從終端裏打開它並執行下面的命令（譯註：命令較長，請勿敲錯）：",-1))]),t[22]||(t[22]=p(`<pre><code>xorriso -as mkisofs -r -checksum_algorithm_iso md5,sha1 -V &#39;Steam OS&#39; -o ~/SteamOSInstaller.iso -J -joliet-long -cache-inodes -no-emul-boot -boot-load-size 4 -boot-info-table -eltorito-alt-boot --efi-boot boot/grub/efi.img -append_partition 2 0x01 ~/SteamOSInstaller/boot/grub/efi.img -partition_offset 16 ~/SteamOSInstaller
</code></pre><p>稍等幾秒鐘之後，SteamOS.iso 文件將會在你的 home 目錄下出現，大約有 1GB。好了，這一步就完成了，下面進入第二步。</p><h3 id="第二步-在-virtualbox-中安裝-steamos" tabindex="-1">第二步，在 VirtualBox 中安裝 SteamOS <a class="header-anchor" href="#第二步-在-virtualbox-中安裝-steamos" aria-label="Permalink to “第二步，在 VirtualBox 中安裝 SteamOS”">​</a></h3><p>如果你已經正確安裝了 VirtualBox 並且瞭解它的正確用法，那麼我們下面需要來建立一個擁有 UEFI 支持的全新虛擬機。在 VirtualBox 的主窗口，點擊 New 按鈕來開始安裝吧。</p><p>在 Name 框輸入 SteamOS，在操作系統類型種選擇 Linux，並在下拉框的版本列表中選擇 Debain 64-bit，點擊 Next 繼續。Memory Size 中設置1024或者2048MB（當然，這取決於你的計算機實際內存大小），我們創建一個 VDI 格式的虛擬硬盤驅動器，將大小固定為15GB。點擊 Continue 來繼續，並等待創建過程結束。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-SteamOS-in-VirtualBox-409363-3.png" alt="Create a new virtual machine"></p><p><em>創建一個新的虛擬機</em></p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-SteamOS-in-VirtualBox-409363-4.png" alt="Set the memory size"></p><p><em>設置內存大小</em></p><p>現在我們的虛擬機已經創建完畢了，接下來讓我們來為 SteamOS 做一些小小的調整。來到 Settings 選項，點擊邊欄的 System，然後在 Boot Order 中取消選擇 &quot;Floppy&quot;，並檢查確認已經選擇 &quot;Enable EFI (special OSes only)&quot; 選項。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-SteamOS-in-VirtualBox-409363-5.png" alt="Enable EFI and remove Floppy"></p><p><em>允許 EFI 並移除 Floppy</em></p><p>接下來，點擊邊欄中的 Display 按鈕，將 Video Memory 設置為128MB，並勾上 &quot;Enable 3D Acceleration&quot; 選項。然後，進入邊欄的 Storage 部分，點擊 &quot;Controller: IDE&quot; 下面的 &quot;Empty&quot;，並點擊 CD/DVD 驅動下拉欄旁邊小 CD 圖標來添加上一步製作的 SteamOSInstall.iso 鏡像文件。當一切完成之後，點擊 OK。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-SteamOS-in-VirtualBox-409363-6.png" alt="Set Video Memory size and 3D acceleration"></p><p><em>設置 Video Memory 大小 和 3D 加速</em></p><p>那麼現在，讓我們按下主窗口中的 &quot;Start&quot; 按鈕來啓動虛擬機。你將會立即看到 SteamOS 啓動畫面。只需要高亮 &quot;Automated install (WILL ERASE DISK)&quot; 後按下 Enter 鍵即可。接下來可以稍微休息一下，直到我們的安裝結束。整個安裝過程可能需要一段時間，當然這取決於你的電腦。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-SteamOS-in-VirtualBox-409363-7.png" alt="Prepare to install SteamOS"></p><p><em>準備安裝 SteamOS</em></p><p>只要我們的安裝過程結束，你就可以關閉虛擬機，然後從 Storage 中移除 ISO 鏡像，然後啓動進入全新的 SteamOS。但是，在我們正式進入 SteamOS 的世界之前，還需要安裝 VirtualBox Guest Additions。先點擊開始 SteamOS 虛擬機，選擇 GRUB 啓動器中的第二個選項（恢復模式），然後在 SteamOS 的命令列提示後輸入下面的命令：</p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-SteamOS-in-VirtualBox-409363-9.png" alt="SteamOS boot loader"></p><pre><code>dpkg --get-selections | grep nvidia
apt-get purge &lt;name of the packages outputted by the above command&gt;
rm /usr/share/X11/xorg.conf.d/55-nvidia.conf
dpkg-reconfigure xserver-xorg
</code></pre><p>進入到 Devices 中然後點擊 Insert Guest Additions CD 鏡像。根據提示來下載 Guest Additions 鏡像，掛載它並執行下面的命令：</p><pre><code>   sh /media/cdrom/VBoxLinuxAdditions.run
</code></pre><p>等待 Guest Additions 安裝完驅動，用下面的命令來重啓我們的虛擬機：</p><pre><code>   shutdown now -r
</code></pre><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-SteamOS-in-VirtualBox-409363-10.png" alt="SteamOS command-line shell prompt"></p><p><em>SteamOS 命令列提示</em></p><p>接下來我們的虛擬機會重啓，讓它啓動進入 SteamOS。當我們抵達登錄提示界面之後，使用 desktop/desktop 或者 steam/steam 作為用户名和密碼來登錄。</p><p>如果您在安裝過程中遇到了一些問題，請別猶豫，在下面評論中告訴我們。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-SteamOS-in-VirtualBox-409363-11.png" alt="SteamOS with GNOME 3"></p><p><em>SteamOS 和 GNOME 3</em></p><hr>`,32)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),i(a,{href:"http://news.softpedia.com/news/How-to-Install-SteamOS-in-VirtualBox-409363.shtml"},{default:s(()=>[...t[5]||(t[5]=[e("http://news.softpedia.com/news/How-to-Install-SteamOS-in-VirtualBox-409363.shtml",-1)])]),_:1})]),o("p",null,[t[9]||(t[9]=e("譯者：",-1)),i(a,{href:"https://github.com/ailurus1991"},{default:s(()=>[...t[7]||(t[7]=[e("pandachow",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:s(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),i(a,{href:"http://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const B=l(S,[["render",u]]);export{I as __pageData,B as default};
